#state-data-dropdown {
  max-width: 100%;
  margin: 0;
  background-color: #f5f5f5;
  padding-top: 4rem;
}

#state-data-wrap {
  margin: 0 auto;
  display: block;
  text-align: center;
  background-image: url('../../assets/img/large_map_transparent.png');
  background-repeat: no-repeat;
  background-position: center 77%;
  h2 {
    &:first-of-type {
      text-transform: uppercase;
    }
  }
  .state-data-headline {
    text-align: initial;
    padding-bottom: 11rem;
  }
  .state-data-dropdown-inner-wrap {
    height: 28rem;
    h2 {
      background-color: rgba(0,33,72,.9);
      height: 11rem;
      padding: 1rem;
      color: #fff;
      width: 100%;
      @media (min-width: $desktop) {
        width: 80%;
      }
      margin: 0 auto;
    }
  }
  .content-container {
    position: relative;
    top: -8rem;
    padding: 1rem;
    select {
      width: 90%;
      @media (min-width: $desktop) {
        width: 55%;
      }
      background-color: rgba(255,255,255,.2);
      color: #fff;
      padding: 0.75rem;
      -webkit-appearance: none;
      -moz-appearance: none;
      background-image: url('../../assets/img/angle-arrow-down-white.svg');
      background-repeat: no-repeat;
      background-size: 15px;
      background-position: 97% 17px;
      option {
        margin: 40px;
        background: rgb(25 35 46 / 94%);
        color: #fff;
        text-shadow: 0 1px 0 rgba(0, 0, 0, 0.4);
      }
    }
  }
}

// Visuals Landing Page groups
.view-visuals-landing-page {
  .view-content {
    .visual-group {
      .view-content {
        text-indent: 20px;
        .visual-group-row {
          .views-field-field-additional-information {
            display: block;
          }
          &:not(:last-of-type) {
            .views-field-field-additional-information {
              display: none;
            }
          }
        }
      }
      .visual-group-title {
        h3 {
          font-weight: 500;
        }
        .item-list {
          li {
            &:not(:last-of-type) {
              display: none;
            }
          }
        }
      }
    }
  }
}

#block-views-block-visuals-landing-page-block-1 {
  .view-content {
    .visual-group {
      .view-content {
        .visual-group-row {
          .views-field-term-node-tid {
            display: none;
          }
        }
      }
    }
  }
  .item-list {
    ul {
      padding: 0;
      li {
        list-style: none;
      }
    }
  }
}