// About Nass pages general
.page-node-type-landing-page {
  article {
    div {
      &>.field--name-field-paragraph-content {
        .paragraph {
          .border-array {
            padding-top: 0;
            .field--name-field-section-head {
              text-transform: capitalize;
              font-weight: 300;
              letter-spacing: 0.2rem;
              font-size: 2rem;
              &:before {
                display: none;
              }
            }
          }
          .field--name-field-section-body {
            &:after {
              display: none;
            }
          }
        }
        .paragraph--type--text {
          h3.career-link {
            margin: 1rem 0;
            a {
              font-weight: 600;
              text-decoration: none;
              color: #005ea2;
              font-size: 1.375rem;
            }
          }
          .our-products-list {
            list-style: none;
            padding: 0;
            li {
              margin: 1rem 0;
              a {
                font-weight: 600;
                text-decoration: none;
                color: #005ea2;
                font-size: 1.375rem;
              }
            }
          }
          h4 {
            font-size: 1.5rem;
            font-weight: 100;
            a {
              color: #005ea2;
              font-weight: bold;
              text-decoration: none;
            }
          }
        }
      }
    }
  }
}

// Hall of Fame
.view-hall-of-fame{
  .view-content {
    .views-row {
      width: 16rem;
      margin: 2rem auto;
      @media (min-width: $tablet) {
        margin: 1rem 0;
      }
      .views-field-field-profile-image {
        img {
          height: 16.25rem;
          width: 12.5rem;
          object-fit: cover;
        }
      }
      .views-field-title {
        a {
          font-weight: 600;
          text-decoration: none;
          color: #005ea2;
          font-size: 1.375rem;
        }
      }
    }
  }
}

.view-leadership-team {
  .view-content {
    .views-row {
      .views-field-field-profile-image {
        img {
          object-fit: cover;
        }
      }

      .views-field-title {
        a {
          font-weight: 600;
          text-decoration: none;
          color: #005ea2;
          font-size: 1.375rem;
        }
      }
    }
  }
}


// Leadership/Hall of Fame Bio
.staff {
  display: block;
  a {
    font-weight: 600;
    text-decoration: none;
    color: #005ea2;
    font-size: 1rem;
    &:before {
      background: url("./../../uswds/img/usa-icons/arrow_back.svg") no-repeat center/contain;
      filter: invert(16%) sepia(100%) saturate(2884%) hue-rotate(191deg) brightness(96%) contrast(101%);
      display: inline-block;
      height: 1rem;
      width: 1rem;
      content: "";
      vertical-align: middle;
      margin-right: 0.2rem;
    }
  }
  .staff-contents {
    margin: 1rem;
    img {
      height: 14.375rem;
      width: 13.625rem;
      object-fit: cover;
    }
    .staff-text {
      h3 {
        font-weight: 100;
        font-size: 2rem;
        margin-bottom: 0.5rem;
        @media (min-width: $tablet) {
          margin-top: 0;
        }
      }
    }
  }
}

// Regional Office Page
#block-views-block-state-list-dropdown-block-block-1 {
  display: none;
  margin: 1rem 0;
  @media (max-width: $tablet) {
    display: inline-block;
    width: 100% !important;
  }
}
#block-views-block-regional-office-list-block-1 {
  @media (max-width: $tablet) {
    .office-list-row {
      width: 100%;
    }
  }
  .office-list-row {
    display: table;
    margin-bottom: 0.5rem;
    cursor: pointer;
    span {
      display: table-cell;
      vertical-align: middle;
      width: 100%;
      padding-left: 10px;
      font-size: 13px;
    }
  }
}
